@propertyWrapper struct Upper {
    var wrappedValue: String
    init(wrappedValue v: String) {
        wrappedValue = v.uppercased() } }
struct Tag { @Upper var name = "swift" }
print(Tag().name)

@propertyWrapper struct Box {
    var wrappedValue: Int
}
struct Cart { @Box var count = 2 }
var cart = Cart(); cart.count += 1
print(cart.count)

@propertyWrapper struct Logged {
    var wrappedValue: Int
    var projectedValue: Int { wrappedValue * 2 }
}
struct Game { @Logged var score = 7 }
print(Game().score, Game().$score)

